const groups={},tests=[];let lines=[];
const test=(name,run)=>tests.push({name,run});
const log=(...args)=>lines.push(args.join(' '));
async function runTests(){for(const {name,run} of tests){if(CASE&&name!==CASE)continue;lines=[];try{await run()}catch(e){log('ERROR',e.name,e.message)}groups[name]=lines.slice()}return groups}
const attempt=fn=>{try{const v=fn();return v===undefined?'ok':v}catch(e){return e.name}};
const done=r=>new Promise(resolve=>r.addEventListener('loadend',()=>setTimeout(resolve,0),{once:true}));
const load=async(path,type='')=>{const r=new XMLHttpRequest();r.open('GET',path);r.responseType=type;const end=done(r);r.send();await end;return r};
const proto=XMLHttpRequest.prototype;
